-- Snowflake Snowsight에서 ACCOUNTADMIN 또는 사용자 변경 권한이 있는 역할로 실행하세요.
USE ROLE ACCOUNTADMIN;

-- 현재 .env.local 개인키와 짝인 공개키를 별도 이름으로 등록합니다.
-- 기존 RSA_PUBLIC_KEY / RSA_PUBLIC_KEY_2 값을 덮어쓰지 않습니다.
ALTER USER BHC28134 ADD KEY PAIR HMRC_VERCEL
  PUBLIC_KEY = ''
  COMMENT = 'Vercel HMRC trade monitor';

-- 등록 결과와 LOGIN_NAME을 확인합니다.
SHOW USER KEY PAIRS FOR USER BHC28134;
DESC USER BHC28134;

